gdjs.NightCode.userFunc0xbf82c8 = function GDJSInlineCode(runtimeScene) {
"use strict";
// === VR near/far fix (undo double division + bypass plugin's closure) ===
var tr = runtimeScene.getGame().getRenderer().getThreeRenderer();
if (!tr || !tr.xr || !tr.xr.isPresenting) return;

var WS = gdjs._webxrVrWorldScale || 90

// Force correct near/far in local (rig) units — 3/100=0.03 m, 100000/100=1000 m
gdjs._webxrVrXrNear = 3 / WS;
gdjs._webxrVrXrFar  = 100000 / WS;

// Override session.updateRenderState ONCE per session to bypass the plugin's
// captured closure values (which lock in whatever wrong values were present at session start).
var sess = tr.xr.getSession ? tr.xr.getSession() : null;
if (sess && !sess._vrNearFarFixed) {
    sess._vrNearFarFixed = true;
    var realURS = Object.getPrototypeOf(sess).updateRenderState;
    sess.updateRenderState = function (init) {
        var p = (init && typeof init === 'object') ? Object.assign({}, init) : {};
        p.depthNear = gdjs._webxrVrXrNear;
        p.depthFar  = gdjs._webxrVrXrFar;
        return realURS.call(sess, p);
    };
    realURS.call(sess, { depthNear: gdjs._webxrVrXrNear, depthFar: gdjs._webxrVrXrFar });
    console.log('[VR Fix] near/far forced to', gdjs._webxrVrXrNear, '/', gdjs._webxrVrXrFar);
}
};
gdjs.NightCode.userFunc0xf8e468 = function GDJSInlineCode(runtimeScene) {
"use strict";
const r  = runtimeScene.getGame().getRenderer().getThreeRenderer();
const sc = runtimeScene.getLayer("").getRenderer().getThreeScene();
if (!sc) return;

const inv = runtimeScene.getRenderer3DInverseWorldScale
  ? runtimeScene.getRenderer3DInverseWorldScale()
  : 0.01;

if (r.xr.isPresenting) {
  // داخل VR: مقیاس صحنه را با مقیاس اکستنشن هماهنگ کن
  gdjs._webxrVrWorldScale = 90;
  sc.scale.set(1, -1, 1);
} else {
  // بیرون از VR: مقدار عادی خود GDevelop برای نمای مانیتور
  sc.scale.set(inv, -inv, inv);
}
};
